/*
 * Simple offline form validation plugin for the login page.
 * Works like the "jQuery Validate" plugin for the options used here:
 * rules (required, minlength), messages and submitHandler.
 */
(function ($) {

    $.fn.validate = function (options) {
        var settings = $.extend({ rules: {}, messages: {}, submitHandler: null }, options);
        var $form = this;
        var clickedButton = null;

        // Remember which submit button was clicked (the PHP code needs its name)
        $form.find(':submit').on('click', function () {
            clickedButton = this;
        });

        // Get the error message for one field
        function getMessage(name, rule) {
            var m = settings.messages[name];
            if (m && typeof m === 'object') { return m[rule] || 'This field is required.'; }
            if (typeof m === 'string') { return m; }
            return rule === 'minlength' ? 'Please enter more characters.' : 'This field is required.';
        }

        // Check one field, show or remove its error message, return true if valid
        function checkField(name) {
            var rule = settings.rules[name];
            var $field = $form.find('[name="' + name + '"]');
            if (!$field.length || !rule) { return true; }

            // Allow the short form: usdusd: "required"
            if (typeof rule === 'string') { var r = {}; r[rule] = true; rule = r; }

            var value = $.trim($field.val() || '');
            var error = '';

            if (rule.required && value === '') {
                error = getMessage(name, 'required');
            } else if (rule.minlength && value.length < rule.minlength) {
                error = getMessage(name, 'minlength');
            }

            // Remove the old message first
            $form.find('label.error[for="' + name + '"]').remove();

            if (error) {
                $('<label class="error"></label>').attr('for', name).text(error).insertAfter($field);
                return false;
            }
            return true;
        }

        // Check all fields when the form is submitted
        $form.on('submit', function (e) {
            var valid = true;
            $.each(settings.rules, function (name) {
                if (!checkField(name)) { valid = false; }
            });

            if (!valid) {
                e.preventDefault();
                return false;
            }

            // Add the clicked button as a hidden field, so $_POST['submit'] is sent to PHP
            if (clickedButton && clickedButton.name) {
                $('<input type="hidden">').attr('name', clickedButton.name)
                    .val(clickedButton.value).appendTo($form);
            }

            if (typeof settings.submitHandler === 'function') {
                e.preventDefault();
                var formEl = $form[0];

                // A button named "submit" hides form.submit(), so use a safe copy of it
                var target = formEl;
                if (typeof formEl.submit !== 'function') {
                    target = {
                        elements: formEl.elements,
                        submit: function () { HTMLFormElement.prototype.submit.call(formEl); }
                    };
                }
                settings.submitHandler(target);
                return false;
            }
        });

        // Re-check a field while typing, only after an error was shown
        $form.on('keyup blur', 'input', function () {
            var name = this.name;
            if (name && settings.rules[name] && $form.find('label.error[for="' + name + '"]').length) {
                checkField(name);
            }
        });

        return this;
    };

})(jQuery);
